const text: PrayerText = {"ashkenaz":[{"id":"eating-barachot-rishonot","heading":"Eating, Barachot Rishonot","lines":[{"he":"לפני אכילת לחם נוטל את ידיו ואומר: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו, וְצִוָּנוּ עַל נְטִילַת יָדָים:","en":"Praised are You, Lord our God, Ruler of the universe, who made us holy with the Divine commandments and commanded us regarding the washing of hands.","note":true},{"he":"על הלחם מברך: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ:","en":"Praised are you, Lord our G-d, Ruler of the universe, who brings forth bread from the earth.","note":true},{"he":"על תבשיל מחמשת מיני דגן ועל מיני מאפה מברך: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא מִינֵי מְזוֹנוֹת:","note":true},{"he":"על היין מברך: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא פְּרִי הַגָּפֶן:","note":true},{"he":"על כל פרי העץ מברך: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא פְּרִי הָעֵץ:","note":true},{"he":"על פרי האדמה מברך: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא פְּרִי הָאֲדָמָה:","note":true},{"he":"על בשר ודגים. חלב וביצה וגבינה. כמהין ופטריות וכדומה. גם על המשקים חוץ מיין אומר: בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ:","note":true}]},{"id":"eating-brachot-achronot-al-hamichyah","heading":"Eating, Brachot Achronot, Al Hamichyah","lines":[{"he":"בָּרוּךְ אַתָּה יְיָ, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם,"},{"he":"על חמשת מיני דגן—עַל הַמִּחְיָה וְעַל הַכַּלְכָּלָה","note":true},{"he":"על היין—עַל הַגֶּפֶן וְעַל פְּרִי הַגֶּפֶן","note":true},{"he":"על פירות משבעת המינים—עַל הָעֵץ וְעַל פְּרִי הָעֵץ","note":true},{"he":"וְעַל תְּנוּבַת הַשָּׂדֶה וְעַל אֶרֶץ חֶמְדָּה טוֹבָה וּרְחָבָה שֶׁרָצִיתָ וְהִנְחַלְתָּ לַאֲבוֹתֵינוּ לֶאֱכוֹל מִפִּרְיָהּ וְלִשְׂבּוֹעַ מִטּוּבָהּ. רַחֵם (נָא) יְיָ אֱלֹהֵינוּ עַל יִשְׂרָאֵל עַמֶּךָ וְעַל יְרוּשָׁלַיִם עִירֶךָ וְעַל צִיּוֹן מִשְׁכַּן כְּבוֹדֶךָ, וְעַל מִזְבְּחֶךָ, וְעַל הֵיכָלֶךָ. וּבְנֵה יְרוּשָׁלַיִם עִיר הַקּדֶשׁ בִּמְהֵרָה בְיָמֵינוּ. וְהַעֲלֵנוּ לְתוֹכָהּ וְשַׂמְּחֵנוּ בְּבִנְיָנָהּ, וְנֹאכַל מִפִּרְיָּהּ וְנִשְׂבַּע מִטּוּבָהּ וּנְבָרֶכְךָ עָלֶיהָ בִּקְדֻשָּׁה וּבְטָהֳרָה. בשבת: וּרְצֵה וְהַחֲלִיצֵנוּ בְּיוֹם הַשַׁבָּת הַזֶּה. בר\"ח: וְזָכְרֵנוּ לְטוֹבָה בְּיוֹם רֹאשׁ הַחֹדֶשׁ הַזֶּה. בר\"ה: וְזָכְרֵנוּ לְטוֹבָה בְּיוֹם הַזִּכָּרוֹן הַזֶּה. ביום טוב ובחוה\"מ: וְשַׂמְּחֵנוּ בְיוֹם בפסח: חַג הַמַּצּוֹת הַזֶּה, בשבועות: חַג הַשָּׁבוּעוֹת הַזֶּה, בסוכות: חַג הַסֻּכּוֹת הַזֶּה, בשמיני עצרת: שְׁמִינִי, חַג עֲצֶרֶת הַזֶּה, בְּיוֹם (טוֹב) מִקְרָא קֹדֶשׁ הַזֶּה. כִּי אַתָּה יְיָ טוֹב וּמֵטִיב לַכּל וְנוֹדֶה לְּךָ עַל הָאָרֶץ"},{"he":"על חמשת מיני דגן—וְעַל הַמִּחְיָה","note":true},{"he":"על היין—וְעַל פְּרִי גַפְנָהּ (בחו\"ל—וְעַל פְּרִי הַגָּֽפֶן)","note":true},{"he":"על פירות משבעת המינים—וְעַל פֵּרוֹתֶיהָ (בחו\"ל—וְעַל הַפֵּרוֹת)","note":true},{"he":"בָּרוּךְ אַתָּה יְיָ, עַל הָאָרֶץ"},{"he":"על חמשת מיני דגן—וְעַל הַמִּחְיָה (וי\"א גם וְעַל הַכַּלְכָּלָה).","note":true},{"he":"על היין—וְעַל פְּרִי גַפְנָהּ (בחו\"ל—וְעַל פְּרִי הַגָּֽפֶן).","note":true},{"he":"על פירות משבעת המינים—וְעַל פֵּרוֹתֶיהָ (בחו\"ל—וְעַל הַפֵּרוֹת).","note":true}]},{"id":"eating-brachot-achronot-borei-nefashot","heading":"Eating, Brachot Achronot, Borei Nefashot","lines":[{"he":"על פירות האילן חוץ מז' מינים ופירות האדמה וירקות ועל כל המשקין ועל דבר שאין גידולו מן הארץ"},{"he":"אחרי האכילה אומר:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא נְפָשׁוֹת רַבּוֹת וְחֶסְרוֹנָן עַל כָּל מַה שֶׁבָּרָאתָּ לְהַחֲיוֹת בָּהֶם נֶפֶשׁ כָּל חָי בָּרוּךְ חֵי חַי הָעוֹלָמִים:","note":true}]},{"id":"blessings-on-sights-sounds-and-smells","heading":"Blessings on Sights Sounds and Smells","lines":[{"he":"ברכות הריח:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, בּוֹרֵא מִינֵי בְשֹמִים:"},{"he":"ברכות *הראיה*:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, עוֹשֹה מַעֲשֹה בְּרֵאשִׁית:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁעָשֹה אֶת הָיַּם הַגָּדוֹל:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, זוֹכֵר הַבְּרִית וְנֶאֱמָן בְּרִיתוֹ וְקַיָּם בַּמַאֲמָרוֹ:"},{"he":"ברכות השמיעה:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, שׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, הַטּוֹב וְהַמֵּטִיב:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, דַּיַּן הָאֱמֶת:"},{"he":"ברכת הקשת: הרואה קשת צריך לברך ברכה זו, ואסור להסתכל בו:"},{"he":"בָּרוּךְ אַתָּה יְ‑יָ אֱ‑לֹהֵינוּ מֶלֶךְ הָעוֹלָם, זוֹכֵר הַבְּרִית נֶאֱמָן בִּבְרִיתוֹ וְקַיָּם בְּמַאֲמָרוֹ:"},{"he":"על הברקים ועל הרעמים:"},{"he":"על הברקים מברך:"},{"he":"בָּרוּךְ עוֹשֹה מַעֲשֹה בְרֵאשִׁית:"},{"he":"על הרעמים מברך:"},{"he":"בָּרוּךְ שֶׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם:"}]}],"sephard":[{"id":"me-ein-shalosh","heading":"Me'ein Shalosh","lines":[{"he":"ברכה אחרונה"},{"he":"ברכה אחרונה מעין שלוש"},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם:"},{"he":"על היין: עַל הַגֶּפֶן וְעַל פְּרִי הַגֶּפֶן:","note":true},{"he":"על פירות משבעת המינים: עַל הָעֵץ וְעַל פְּרִי הָעֵץ:","note":true},{"he":"על מזונות: עַל הַמִחְיָה וְעַל הַכַּלְכָּלָה:","note":true},{"he":"על מזונות ויין ביחד: עַל הַמִּחְיָה וְעַל הַכַּלְכָּלָה וְעַל הַגֶּפֶן וְעַל פְּרִי הַגֶּפֶן:","note":true},{"he":"וְעַל תְּנוּבַת הַשָּׂדֶה וְעַל אֶרֶץ חֶמְדָּה טוֹבָה וּרְחָבָה שֶׁרָצִיתָ וְהִנְחַלְתָּ לַאֲבוֹתֵינוּ לֶאֱכֹל מִפִּרְיָהּ וְלִשְׂבּוֹעַ מִטּוּבָהּ, רַחֵם (נָא) יְהֹוָה אֱלֹהֵינוּ עַל יִשְׂרָאֵל עַמֶּךָ וְעַל יְרוּשָׁלַיִם עִירֶךָ וְעַל צִיּוֹן מִשְׁכַּן כְּבוֹדֶךָ וְעַל מִזְבְּחֶךָ וְעַל הֵיכָלֶךָ, וּבְנֵה יְרוּשָׁלַיִם עִיר הַקֹּדֶשׁ בִּמְהֵרָה בְּיָמֵינוּ וְהַעֲלֵנוּ לְתוֹכָהּ וְשַׂמְּחֵנוּ בְּבִנְיָנָהּ וְנֹאכַל מִפִּרְיָּהּ וְנִשְׂבַּע מִטּוּבָהּ וּנְבָרֶכְךָ עָלֶיהָ בִּקְדֻשָּׁה וּבְטָהֳרָה:"},{"he":"(בשבת:) וּרְצֵה וְהַחֲלִיצֵנוּ בְּיוֹם הַשַּׁבָּת הַזֶּה:","note":true},{"he":"(בר\"ח:) וְזָכְרֵנוּ לְטוֹבָה בְּיוֹם רֹאשׁ הַחֹדֶשׁ הַזֶּה:","note":true},{"he":"(בר\"ה:) וְזָכְרֵנוּ לְטוֹבָה בְּיוֹם הַזִּכָּרוֹן הַזֶּה:","note":true},{"he":"(ביו\"ט:) וְשַׂמְחֵנוּ בְּיוֹם חַג (פלוני) הַזֶּה:","note":true},{"he":"כִּי אַתָּה יְהֹוָה טוֹב וּמֵטִיב לַכֹּל וְנוֹדֶה לְךָ עַל הָאָרֶץ וְעַל:"},{"he":"(על היין:) פְּרִי הַגָּפֶן: בָּרוּךְ אַתָּה יְהֹוָה עַל הָאָרֶץ וְעַל פְּרִי הַגָּפֶן: ( בא\"י וְעַל פְּרִי גַפְנָהּ):","note":true},{"he":"(על הפירות:) הַפֵּרוֹת: בָּרוּךְ אַתָּה יְהֹוָה עַל הָאָרֶץ וְעַל הַפֵּרוֹת: ( בא\"י וְעַל פֵּרוֹתֶיהָ):","note":true},{"he":"(על מזונות:) הַמִחְיָה: בָּרוּךְ אַתָּה יְהֹוָה עַל הָאָרֶץ וְעַל הַמִחְיָה וְעַל הַכַּלְכָּלָה:","note":true},{"he":"(על מזונות ויין ביחד:) הַמִּחְיָה וְעַל פְּרִי הַגָּפֶן: בָּרוּךְ אַתָּה יְהֹוָה עַל הָאָרֶץ וְעַל הַמִחְיָה וְעַל הַכַּלְכָּלָה וְעַל פְּרִי הַגָּפֶן: ( בא\"י וְעַל פְּרִי גַפְנָהּ):","note":true}]},{"id":"ha-etz","heading":"Ha'etz","lines":[{"he":"בורא פרי העץ"},{"he":"על כל פרי העץ מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא פְּרִי הָעֵץ:"}]},{"id":"ha-adamah","heading":"Ha'adamah","lines":[{"he":"בורא פרי האדמה"},{"he":"על פרי האדמה מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא פְּרִי הָאֲדָמָה:"}]},{"id":"shehakol","heading":"Shehakol","lines":[{"he":"ברכת שהכל"},{"he":"על בשר ודגים. חלב וביצה וגבינה. כמהין ופטריות וכדומה. גם על המשקים חוץ מיין אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ:"}]},{"id":"borei-nefashot","heading":"Borei Nefashot","lines":[{"he":"בורא נפשות"},{"he":"על פירות האילן חוץ מז' מינים ופירות האדמה וירקות ועל כל המשקין ועל דבר שאין גידולו מן הארץ מברכין אחר אכילתן זה:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם בּוֹרֵא נְפָשׁוֹת רַבּוֹת וְחֶסְרוֹנָן עַל כָּל מַה שֶׁבָּרָאתָ לְהַחֲיוֹת בָּהֶם נֶפֶשׁ כָּל חָי. בָּרוּךְ חֵי הָעוֹלָמִים:"}]},{"id":"shehecheyanu","heading":"Shehecheyanu","lines":[{"he":"ברכת שהחיינו"},{"he":"הלובש מלבוש חדש וכן האוכל פרי חדש הגדל בזמן קבוע בשנה ומתחדש משנה לשנה מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם שֶׁהֶחֱיָנוּ וְקִיְּמָנוּ וְהִגִּיעָנוּ לַזְמַן הַזֶּה:"}]},{"id":"fragrant-spices","heading":"Fragrant Spices","lines":[{"he":"ריח בשמים"},{"he":"על ריח בשמים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, בּוֹרֵא מִינֵי בְשָׂמִים:"}]},{"id":"fragrant-herbs","heading":"Fragrant Herbs","lines":[{"he":"ריח טוב שבעשבים"},{"he":"על ריח טוב שבעשבים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, בּוֹרֵא עִשְׂבֵּי בְשָׂמִים:"}]},{"id":"fragrant-shrubs","heading":"Fragrant Shrubs","lines":[{"he":"ריח טוב שבעצים"},{"he":"על ריח טוב שבעצים ושיחים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, בּוֹרֵא עֲצֵי בְשָׂמִים:"}]},{"id":"fragrant-fruit","heading":"Fragrant Fruit","lines":[{"he":"ריח טוב שבפירות"},{"he":"על ריח טוב שבפירות מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, הַנּוֹתֵן רֵיחַ טוֹב בַּפֵּירוֹת:"}]},{"id":"fragrant-oils","heading":"Fragrant Oils","lines":[{"he":"שמן אפרסמון"},{"he":"על שמן אפרסמון מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, בּוֹרֵא שֶׁמֶן עָרֵב:"}]},{"id":"lightning-thunder","heading":"Lightning & Thunder","lines":[{"he":"בִּרְכַּת ברקים ורעמים"},{"he":"על הברקים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, עוֹשֶׂה מַעֲשֶׂה בְּרֵאשִׁית:"},{"he":"על הרעמים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם:"}]},{"id":"seeing-rainbow","heading":"Seeing Rainbow","lines":[{"he":"בִּרְכַּת הקשת","en":"Blessing over a rainbow"},{"he":"הרואה קשת צריך לברך ברכה זו:","en":"One who sees a rainbow should recite this blessing:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, זוֹכֵר הַבְּרִית נֶאֱמָן בִּבְרִיתוֹ וְקַיָּם בְּמַאֲמָרוֹ:","en":"Blessed are You, Lord our God, King of the universe, who remembers the covenant, is faithful with [God's] covenant, and is steady with [God's] word."}]},{"id":"seeing-ocean","heading":"Seeing Ocean","lines":[{"he":"הים הגדול"},{"he":"הרואה את הים הגדול מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, עֹשֶׂה אֶת הַיָּם הַגָּדוֹל:"}]},{"id":"blossoming-fruit-tree","heading":"Blossoming Fruit Tree","lines":[{"he":"בִּרְכַּת הָאִילָנוֹת"},{"he":"הרואה אילני מאכל (לפחות שני אילנות) בפריחתם בימי ניסן מברך פעם אחת בשנה:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁלֹּא חִסֵּר בְּעוֹלָמוֹ כְּלוּם, וּבָרָא בוֹ בְּרִיוֹת טוֹבוֹת וְאִילָנוֹת טוֹבוֹת, לֵהָנוֹת בָּהֶם בְּנֵי אָדָם:"}]},{"id":"various-blessings-of-praise","heading":"Various Blessings of Praise","lines":[{"he":"ברכות שונות"},{"he":"הרואה חכם גדול מישראל אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁחָלַק מֵחָכְמָתוֹ לִירֵיאָיו:"},{"he":"הרואה חכם גדול מאומות העולם אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁנָתַן מֵחָכְמָתוֹ לְבָשָׂר וָדָם:"},{"he":"הרואה מלך מישראל אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁחָלַק מִכְּבוֹדוֹ לִירֵיאָיו:"},{"he":"הרואה מלך מאומות העולם אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁנָתַן מִכְּבוֹדוֹ לְבָשָׂר וָדָם:"},{"he":"הרואה בתי כנסיות בחורבנן מברך דיין האמת, ובישובן מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, מַצִיב גְּבוּל אַלְמָנָה:"},{"he":"הרואה מקום שנעשו בו ניסים לישראל, כגון מעברות הירדן וחומות יריחו אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁעָשָׂה נִיסִּים לַאֲבוֹתֵינוּ בַּמָּקוֹם הַזֶּה:"},{"he":"הרואה מקום שנעשה בו נס לו, או לרבו, או לאבותיו, או לאבותינו בכלל, מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁעָשָׂה לִי (לְרַבִּי, לַאֲבוֹתַי, לַאֲבוֹתֵינוּ) נֵס בַּמָּקוֹם הַזֶּה:","note":true},{"he":"כשרואין בריה משונה, כגון גמד, וכושי וכדומה אומר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, מְשַׁנֶּה הַבְּרִיּוֹת:"},{"he":"הרואה חבירו החביב לו אחר ל' יום מברך שהחיינו, ואחר י\"ב חודש מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, מְחַיֶה הַמֵּתִים:"},{"he":"הרואה אילנות טובים ובריות נאות, מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, שֶׁכָּכָה לוֹ בְּעוֹלָמוֹ:"},{"he":"מי שלא ראה קברי ישראל שלשים יום יברך בראייתם:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, אֲשֶׁר יָצַר אֶתְכֶם בְּדִּין, וְזָן וְכִלְכֵּל אֶתְכֶם בְּדִּין, וְהֵמִית אֶתְכֶם בְּדִּין, וְיוֹדֵעַ מִסְפַּר כֻּלְּכֶם בְּדִין, וְעָתִיד לְהַחֲזִיר וּלְהַחֲיוֹתכֶם בַּדִּין. בָּרוּךְ אַתָּה יְהֹוָה מְחַיֵּה הַמֵּתִים:"},{"he":"בפעם הראשונה שיורדים גשמים הרבה בארץ ישראל, ובחו\"ל לאחר עצירת גשמים שהיה העולם בצער מברך:","note":true},{"he":"מוֹדִים אֲנַחְנוּ לָךְ יְהֹוָה אֱלֹהֵינוּ על כל טפה וטפה שהורדת לנו וְאִלּוּ פִינוּ מָלֵא שִׁירָה כַּיָּם. וּלְשׁוֹנֵנוּ רִנָּה כַּהֲמוֹן גַּלָּיו. וְשִׂפְתוֹתֵינוּ שֶׁבַח כְּמֶרְחֲבֵי רָקִיעַ. וְעֵינֵינוּ מְאִירוֹת כַּשֶּׁמֶשׁ וְכַיָּרֵחַ. וְיָדֵינוּ פְרוּשׂוֹת כְּנִשְׁרֵי שָׁמָיִם. וְרַגְלֵינוּ קַלּוֹת כָּאַיָּלוֹת. אֵין אֲנַחְנוּ מַסְפִּיקִים לְהוֹדוֹת לְךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. וּלְבָרֵךְ אֶת שִׁמְךָ מַלְכֵּנוּ. עַל אַחַת מֵאָלֶף אֶלֶף אַלְפֵי אֲלָפִים וְרִבֵּי רְבָבוֹת פְּעָמִים. הַטּוֹבוֹת נִסִּים וְנִפְלָאוֹת שֶׁעָשִׂיתָ עִם אֲבוֹתֵינוּ וְעִמָּנוּ: מִלְּפָנִים מִמִּצְרַיִם גְּאַלְתָּנוּ יְהֹוָה אֱלֹהֵינוּ. וּמִבֵּית עֲבָדִים פְּדִיתָנוּ. בְּרָעָב זַנְתָּנוּ. וּבְשָׂבָע כִּלְכַּלְתָּנוּ. מֵחֶרֶב הִצַּלְתָּנוּ. וּמִדֶּבֶר מִלַּטְתָּנוּ. וּמֵחֳלָיִם רָעִים וְרַבִּים וְנֶאֱמָנִים דִּלִּיתָנוּ: עַד הֵנָּה עֲזָרוּנוּ רַחֲמֶיךָ. וְלֹא עֲזָבוּנוּ חֲסָדֶיךָ יְהֹוָה אֱלֹהֵינוּ. וְאַל תִּטְּשֵׁנוּ יְהֹוָה אֱלֹהֵינוּ לָנֶצַח: עַל כֵּן אֵבָרִים שֶׁפִּלַּגְתָּ בָּנוּ. וְרוּחַ וּנְשָׁמָה שֶׁנָּפַחְתָּ בְּאַפֵּינוּ. וְלָשׁוֹן אֲשֶׁר שַׂמְתָּ בְּפִינוּ. הֵן הֵם. יוֹדוּ וִיבָרְכוּ וִישַׁבְּחוּ וִיפָאֲרוּ וִישׁוֹרְרוּ וִירוֹמְמוּ וְיַעֲרִיצוּ וְיַקְדִּישׁוּ וְיַמְלִיכוּ אֶת שִׁמְךָ מַלְכֵּנוּ. בָּרוּךְ אַתָּה יְהֹוָה אֵל רוֹב הַהוֹדָאוֹת:"},{"he":"ובא\"י אם השנים כתיקונן יברך בלא שם ומלכות (עי' מ\"ב סי' רכא סק\"א ובבה\"ל שם):","note":true},{"he":"על פדיון פטר חמור יברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו, וְצִוָּנוּ עַל פִּדְיוֹן פֶּטֶר חֲמוֹר:"}]},{"id":"immersing-utensils","heading":"Immersing Utensils","lines":[{"he":"בִּרְכַּת טְבִילַת כְּלִים"},{"he":"כשטובל כלים חדשים מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל טְבִילַת כֶּלִי: (כשהם הרבה אומר: כֵּלִים:)","note":true}]},{"id":"mezuzah","heading":"Mezuzah","lines":[{"he":"בִּרְכַּת הַמְזוּזָה"},{"he":"הקובע מזוזה מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לִקְבֹּעַ מְזוּזָה:"}]},{"id":"separating-challah","heading":"Separating Challah","lines":[{"he":"סֵדֶר הַפְרָשַׁת חַלָּה"},{"he":"א. בזמנינו שהחלה אסורה באכילה לכהנים מפני הטומאה, לֹא נותנים אוֹתה לכהנים אלא שורפים אוֹתה. ומפרישים רק כל שהוא מבלי כל שיעור.","note":true},{"he":"ב. את החלה שמפרישים צריך לשרוף, ואסור לזורקה לאשפה ולזלזל בקדושתה. ורק לאחר ששרפה אוֹתה מותר לזורקה לאשפה, כיון שכבר נעשה מצוותה, ואין בזה משום זלזול. ואם אין אפשרות לשורפה, תכרוך את החלה פעמיים בנייר ותכניסה לפח הזבל."},{"he":"ג. טוב להמתין מלהפריש חלה עד לאחר גמר הלישה - כשתֵעשה העיסה גוש אחד. ואם לֹא הפרישה מן העיסה ואפתה - מפרישה מן הפת לאחר האפיה."},{"he":"ד. אין חיוב הפרשת חלה אלא מעיסה העומדת לאפיה. אבל העושה עיסה כדי לבשלה אוֹ לטגנה, מפרישה ממנה חלה בלי ברכה, ורק אם רוצה לאפות קצת ממנה - מפרישה ממנה חלה בברכה."},{"he":"ה. שעור הפרשת חלה בברכה הוא כשיש בקמח שיעור של 1560 גר', וממדת חסידות טוב להפריש חלה בלי ברכה משיעור קילו וחצי לערך (שו\"ת חזו\"ע עמ' תקיח). ולשיטת החזו\"א השעור הוא 2250 גר'.","note":true},{"he":"קודם ההפרשה מברכת:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם, אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו, וְצִוָּנוּ לְהַפְרִישׁ חַלָּה מִן הָעִיסָה:"},{"he":"ואחר כך לוקחת חתיכה כל שהיא ומרימה ביד ימין ואומרת:","note":true},{"he":"הֲרֵי זוֹ חַלָּה:"}]},{"id":"separating-terumot-maasrot","heading":"Separating Terumot & Maasrot","lines":[{"he":"סֵדֶר הַפְרָשַׁת תְּרוּמוֹת וּמַעַשְׂרוֹת"},{"he":"כל גידולי קרקע הגדלים בארץ יִשְׂרָאֵל בבעלות יהודי, חייבים בתרומות ומעשרות. וכל גידול קרקע שאינו ידוע אם הופרשו ממנו תרומות ומעשרות אוֹ לֹא, הרי הוּא בחזקת דמאי, וחייב להפריש ממנו תרומות ומעשרות בלי ברכה. ואם ודאי שלא הופרשו ממנו תרומות ומעשרות מפריש בברכה, דהיינו שלפני שיפריש יברך את הברכה ואחר כך יאמר את נוסח ההפרשה:","note":true},{"he":"סדר הפרשת תרומות ומעשרות עפ\"י פסקי החזון איש זצ\"ל","note":true},{"he":"נוטל מן הפרות יותר מאחד ממאה ומבדילו מן השאר ואומר:","note":true},{"he":"אם הפירות טבל ודאי יאמר לפני הנוסח:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהַפְרִישׁ תְּרוּמוֹת וּמַעְשְׂרוֹת.","note":true},{"he":"יוֹתֵר מֵאֶחָד מִמֵּאָה שֶׁיֵּשׁ כַּאן הֲרֵי הוּא תְּרוּמָה גְּדוֹלָה בְּצַד צְפוֹנוֹ [כָּל מִין עַל מִינוֹ], אוֹתוֹ אֶחָד מִמֵּאָה שֶׁיֵּשׁ כַּאן וְעוֹד תִּשְׁעָה חֲלָקִים כְּמוֹתוֹ בְּצַד צְפוֹנוֹ שֶׁל הַפֵּירוֹת [כָּל מִין עַל מִינוֹ] הֲרֵי הוּא מַעֲשֵׂר רִאשׁוֹן. אוֹתוֹ אֶחָד מִמֵּאָה שֶׁעֲשִׂיתִיו מַעֲשֵׂר רִאשׁוֹן עָשׂוּי תְּרוּמַת מַעֲשֵׂר [כָּל מִין עַל מִינוֹ] וּמַעֲשֵׂר שֵׁנִי בְּצַד דְּרוֹמוֹ [כָּל מִין עַל מִינוֹ] [וְאִם צָרִיךְ מַעֲשֵׂר עָנִי יְהֵא מַעֲשֵׂר עָנִי בְּצַד דְּרוֹמוֹ.]"},{"he":"אם הפירות טבל ודאי יאמר לפני הנוסח:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל פִּדְיוֹן מַעֲשֵׂר שֵׁנִי.","note":true},{"he":"אם הפירות ודאי נטע רבעי וטבל יאמר:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְשָׁנוּ בְּמִצְוֹתָיו, וְצִוָּנוּ עַל פִּדְיוֹן נֶטַע רְבָעִי.","note":true},{"he":"וּמְחוּלָל הוּא וְחוּמְשׁוֹ עַל שְׁתֵּי פְרוּטוּת שֶׁבִּרְשׁוּתִי לְחִילּוּל מַעֲשֵׂר שֵׁנִי וֶנֶטַע רְבָעִי.","note":true}]},{"id":"mealtime-blessings","heading":"Mealtime Blessings","lines":[{"he":"סדר סעודה וברכותיה"},{"he":"קודם הסעודה יטול ידיו ויברך:","note":true},{"he":"שְׂאוּ יְדֵיכֶם קוֹדֶשׁ וּבָרְכוּ אֶת יְהֹוָה: וְאֶשָׂא כַפַּי אֶל מִצְוֹתֶיךָ אֲשֶׁר אָהַבְתִּי וְאָשִׂחָה בְחֻקֶּיךָ:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו, וְצִוָּנוּ עַל נְטִילַת יָדָיִם:","en":"...Blessed are You, Lord our God, King of the universe, who has sanctified us with His commandments and Commanded us regarding the washing of hands."},{"he":"על הלחם מברך:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ:"}]}],"edot":[{"id":"blessings-on-enjoyments","heading":"Blessings on Enjoyments","lines":[{"he":"ברכות הנהנין","en":"Blessings on Enjoyments"},{"he":"על תבשיל מחמשת מיני דגן ועל מאפה ממינים אלה (חוץ מן הלחם), ועל האורז מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא מִינֵי מְזוֹנוֹת:","en":"Blessed are You, L·rd, Our G·d, King of the Universe Who creates varieties of foods"},{"he":"על היין מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא פְּרִי הַגֶּֽפֶן:","en":"Blessed are You, L·rd, Our G·d, King of the Universe Who creates fruit of the vine"},{"he":"על פירות העץ מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא פְּרִי הָעֵץ:","en":"Blessed are You, L·rd, Our G·d, King of the Universe Who creates fruit of the tree"},{"he":"על פירות האדמה מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא פְּרִי הָאֲדָמָה:","en":"Blessed are You, L·rd, Our G·d, King of the Universe Who creates fruit of the ground"},{"he":"על דבר שאין גדולו מן הארץ כגון בשר, דגים, חלב, גבינה, וכדומה. וכן על משקים (חוץ מן היין) מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ:","en":"Blessed are You, L·rd, Our G·d, King of the Universe that all was (made) by His word"},{"he":"לאחר האכילה אם אכל כזית בכדי אכילת פרס (4 דקות, וי\"א 8 דקות), או שתה רביעית בבת אחת על פרות האילן (חוץ מן הז' מינים), פרות האדמה, ודבר שאין גידולו מן הארץ, מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא נְפָשׁוֹת רַבּוֹת וְחֶסְרוֹנָן עַל כָּל־מַה־שֶּׁבָּרָֽאתָ לְהַחֲיוֹת בָּהֶם נֶֽפֶשׁ כָּל־חָי, בָּרוּךְ חַי הָעוֹלָמִים.","en":"Blessed are You, L·rd, our G·d, King of the universe, Who creates Many Souls, & their lackings on all that You created to give life to them – all living souls. Blessed is He Who lives Forever."},{"he":"על ריח טוב שבעצים מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא עֲצֵי בְשָׂמִים:"},{"he":"על ריח טוב שבעשבים מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא עִשְׂבֵּי בְשָׂמִים:"},{"he":"על ריח טוב שאינו עץ ולא עשב, או שהוא מסופק בו בין עץ לעשב, מברך","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, בּוֹרֵא מִינֵי בְשָׂמִים:"},{"he":"כל בגד שהוא שמח בו, אפילו שלאחרים אין שמחה בבגד זה הרי זה מברך שהחיינו, וכן להיפך. וכן מברכים שהחיינו על פרי המתחדש משנה לשנה, ויש זמן קבוע לגידולו. אבל פירות שאין בהם היכר בין ישנים לחדשים, כגון אגוזים, שקדים, ותפוחים שנמצאים בשוק כל השנה וכדומה, אף על פי שהם מתחדשים משנה לשנה, ויודע באלו שהם חדשים, אפילו הכי לא יברך עליהם שהחיינו, מאחר שאין היכר בין חדשים לישנים. המנהג הוא לברך באכילת פרי חדש ברכת הפרי ואחר כך שהחיינו"},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם, שֶׁהֶחֱיָֽנוּ וְקִיְּמָֽנוּ וְהִגִּיעָֽנוּ לַזְּמַן הַזֶּה:"}]},{"id":"al-hamihya","heading":"Al Hamihya","lines":[{"he":"ברכת מעין שלוש"},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, אֱלֹהֵֽינוּ מֶֽלֶךְ הָעוֹלָם"},{"he":"אם אכל מזונות יאמר עַל הַמִּחְיָה וְעַל הַכַּלְכָּלָה","note":true},{"he":"אם שתה יין יאמר (וְ)עַל הַגֶּֽפֶן וְעַל פְּרִי הַגֶּֽפֶן","note":true},{"he":"אם אכל פרות משבעת המינים יאמר (וְ)עַל הָעֵץ וְעַל פְּרִי הָעֵץ","note":true},{"he":"וְעַל תְּנוּבַת הַשָּׂדֶה, וְעַל אֶֽרֶץ חֶמְדָּה טוֹבָה וּרְחָבָה, שֶׁרָצִֽיתָ וְהִנְחַֽלְתָּ לַאֲבוֹתֵֽינוּ, לֶאֱכֹל מִפִּרְיָהּ וְלִשְׂבֹּֽעַ מִטּוּבָהּ. רַחֵם יְהֹוָה אֱלֹהֵֽינוּ עָלֵֽינוּ וְעַל יִשְׂרָאֵל עַמָּךְ, וְעַל יְרוּשָׁלַֽיִם עִירָךְ, וְעַל הַר צִיּוֹן מִשְׁכַּן כְּבוֹדָךְ, וְעַל מִזְבָּחָךְ וְעַל הֵיכָלָךְ. וּבְנֵה יְרוּשָׁלַֽיִם עִיר הַקֹּֽדֶשׁ בִּמְהֵרָה בְיָמֵֽינוּ, וְהַעֲלֵֽנוּ לְתוֹכָהּ, וְשַׂמְּחֵֽנוּ בְּבִנְיָנָהּ, וּנְבָֽרְכָֽךְ עָלֶֽיהָ בִּקְדֻשָּׁה וּבְטָהֳרָה:"},{"he":"בשבת וּרְצֵה וְהַחֲלִיצֵֽנוּ בְּיוֹם הַשַּׁבָּת הַזֶּה.","note":true},{"he":"בראש־חודש וְזָכְרֵֽנוּ לְטוֹבָה בְּיוֹם רֹאשׁ חֹֽדֶשׁ הַזֶּה.","note":true},{"he":"בראש־השנה וְזָכְרֵֽנוּ לְטוֹבָה בְּיוֹם הַזִּכָּרוֹן הַזֶּה.","note":true},{"he":"בפסח וְשַׂמְּחֵֽנוּ בְּיוֹם חַג הַמַּצּוֹת הַזֶּה, בְּיוֹם ביום טוב: טוֹב מִקְרָא קֹדֶשׁ הַזֶּה.","note":true},{"he":"בשבועות וְשַׂמְּחֵֽנוּ בְּיוֹם חַג הַשָּׁבוּעוֹת הַזֶּה בְּיוֹם טוֹב מִקְרָא קֹֽדֶשׁ הַזֶּה.","note":true},{"he":"בסוכות וְשַׂמְּחֵֽנוּ בְּיוֹם הַסֻּכּוֹת הַזֶּה, בְּיוֹם ביום טוב: טוֹב מִקְרָא קֹֽדֶשׁ הַזֶּה.","note":true},{"he":"בשמיני עצרת וְשַׂמְּחֵֽנוּ בְּיוֹם שְׁמִינִי חַג עֲצֶֽרֶת הַזֶּה בְּיוֹם טוֹב מִקְרָא קֹֽדֶשׁ הַזֶּה.","note":true},{"he":"כִּי אַתָּה טוֹב וּמֵטִיב לַכֹּל, וְנוֹדֶה לְךָ עַל הָאָֽרֶץ"},{"he":"מזונות וְעַל הַמִּחְיָה וְעַל הַכַּלְכָּלָה של ארץ ישראל וְעַל מִחְיָתָהּ וְעַל כַּלְכָּלָתָהּ","note":true},{"he":"יין וְעַל פְּרִי הַגֶּֽפֶן של ארץ ישראל וְעַל פְּרִי גַפְנָהּ","note":true},{"he":"פירות וְעַל הַפֵּרוֹת של ארץ ישראל וְעַל פֵּרוֹתֶֽיהָ","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה, עַל הָאָֽרֶץ וְעַל"},{"he":"מזונות הַמִּחְיָה וְעַל הַכַּלְכָּלָה: של ארץ ישראל מִחְיָתָהּ וְעַל כַּלְכָּלָתָהּ:","note":true},{"he":"יין פְּרִי הַגֶּֽפֶן: של ארץ ישראל פְּרִי גַפְנָהּ:","note":true},{"he":"פירות הַפֵּרוֹת: של ארץ ישראל פֵּרוֹתֶֽיהָ:","note":true}]}]};

